INSERT INTO public.documents (doc_key, standard_number, title, division, sector, year, status, enforcement, summary, tags, source_url, full_text, data_origin) VALUES ('std-302-2-201', 'IS 302-2-201', 'Safety of household and similar electrical appliances — Particular requirements for electric kettles', 'Electrotechnical (ETD)', 'Electrical Appliances', 2019, 'Active', 'ISI Mark (Mandatory)', 'Particular safety requirements for electric kettles and jug kettles for household use, covering temperature rise, dry-boil protection, leakage current and marking.', ARRAY['kettle', 'household appliance', 'safety', 'ISI']::text[], 'https://www.bis.gov.in/standards/', 'Particular safety requirements for electric kettles and jug kettles for household use, covering temperature rise, dry-boil protection, leakage current and marking. Marking and instructions: Appliances shall be marked with rated voltage, rated power input, manufacturer''s name or trade mark and model reference, in a durable and legible manner. Heating: Under normal operation, temperature rise of handles, knobs and grips shall not exceed the limits specified; kettles shall not attain excessive temperature when operated without water.', 'Sample');
INSERT INTO public.chunks (document_id, chunk_text, clause_ref, heading) SELECT id, 'Particular safety requirements for electric kettles and jug kettles for household use, covering temperature rise, dry-boil protection, leakage current and marking.', 'Overview', 'Summary' FROM public.documents WHERE doc_key='std-302-2-201';
INSERT INTO public.chunks (document_id, chunk_text, clause_ref, heading) SELECT id, 'Appliances shall be marked with rated voltage, rated power input, manufacturer''s name or trade mark and model reference, in a durable and legible manner.', 'Clause 7.1', 'Marking and instructions' FROM public.documents WHERE doc_key='std-302-2-201';
INSERT INTO public.chunks (document_id, chunk_text, clause_ref, heading) SELECT id, 'Under normal operation, temperature rise of handles, knobs and grips shall not exceed the limits specified; kettles shall not attain excessive temperature when operated without water.', 'Clause 11', 'Heating' FROM public.documents WHERE doc_key='std-302-2-201';
