INSERT INTO public.chunks (document_id, chunk_text, clause_ref, heading) SELECT id, 'Every water heater shall be fitted with a non-self-resetting thermal cut-out in addition to the thermostat, and a pressure relief device.', 'Clause 6.3', 'Safety devices' FROM public.documents WHERE doc_key='std-2082';
