INSERT INTO public.documents (doc_key, standard_number, title, division, sector, year, status, enforcement, summary, tags, source_url, full_text, data_origin) VALUES ('std-4151', 'IS 4151', 'Protective helmets for two-wheeler riders — Specification', 'Transport Engineering (TED)', 'Personal Protective Equipment', 2015, 'Active', 'ISI Mark (Mandatory)', 'Requirements for protective helmets for riders of two-wheeled motor vehicles, including shock absorption, penetration resistance and retention system.', ARRAY['helmet', 'two wheeler', 'safety', 'ISI']::text[], 'https://www.bis.gov.in/standards/', 'Requirements for protective helmets for riders of two-wheeled motor vehicles, including shock absorption, penetration resistance and retention system. Shock absorption: When tested at the specified impact sites, the peak acceleration transmitted to the headform shall not exceed 300 g. Mass of helmet: The mass of a full-face helmet, complete with all accessories, shall not exceed 1.2 kg.', 'Sample');
