INSERT INTO public.documents (doc_key, standard_number, title, division, sector, year, status, enforcement, summary, tags, source_url, full_text, data_origin) VALUES ('std-1417', 'IS 1417', 'Grading, marking and hallmarking of gold and gold alloy jewellery/artefacts', 'Chemical (CHD)', 'Precious Metals', 2016, 'Active', 'Hallmarking (Mandatory)', 'Permitted finenesses for gold jewellery, hallmark composition including the BIS mark, purity in carat and fineness, and the six-digit alphanumeric HUID.', ARRAY['gold', 'hallmark', 'HUID', 'jewellery']::text[], 'https://www.bis.gov.in/hallmarking/', 'Permitted finenesses for gold jewellery, hallmark composition including the BIS mark, purity in carat and fineness, and the six-digit alphanumeric HUID. Permitted finenesses: Gold jewellery shall be graded in the permitted finenesses, including 14 carat (585), 18 carat (750), 20 carat (833), 22 carat (916) and 23 carat (958). Hallmark components: The hallmark shall consist of the BIS standard mark, the purity/fineness grade and the six-digit alphanumeric HUID.', 'Sample');
INSERT INTO public.chunks (document_id, chunk_text, clause_ref, heading) SELECT id, 'Permitted finenesses for gold jewellery, hallmark composition including the BIS mark, purity in carat and fineness, and the six-digit alphanumeric HUID.', 'Overview', 'Summary' FROM public.documents WHERE doc_key='std-1417';
