INSERT INTO public.documents (doc_key, standard_number, title, division, sector, year, status, enforcement, summary, tags, source_url, full_text, data_origin) VALUES ('std-16046', 'IS 16046', 'Secondary cells and batteries containing alkaline or other non-acid electrolytes — Safety', 'Electrotechnical (ETD)', 'Electronics and IT', 2018, 'Active', 'CRS (Mandatory)', 'Safety requirements for lithium-ion cells and battery packs used in portable applications and power banks.', ARRAY['battery', 'lithium ion', 'CRS', 'power bank']::text[], 'https://www.bis.gov.in/product-certification/', 'Safety requirements for lithium-ion cells and battery packs used in portable applications and power banks. Abuse testing: Cells shall not explode or catch fire when subjected to the specified external short circuit and thermal abuse conditions.', 'Sample');
INSERT INTO public.chunks (document_id, chunk_text, clause_ref, heading) SELECT id, 'Safety requirements for lithium-ion cells and battery packs used in portable applications and power banks.', 'Overview', 'Summary' FROM public.documents WHERE doc_key='std-16046';
INSERT INTO public.chunks (document_id, chunk_text, clause_ref, heading) SELECT id, 'Cells shall not explode or catch fire when subjected to the specified external short circuit and thermal abuse conditions.', 'Clause 7.3', 'Abuse testing' FROM public.documents WHERE doc_key='std-16046';
INSERT INTO public.documents (doc_key, standard_number, title, division, sector, year, status, enforcement, summary, tags, source_url, full_text, data_origin) VALUES ('std-15644', 'IS 15644', 'Safety of electric toys', 'Production and General Engineering (PGD)', 'Toys', 2006, 'Active', 'ISI Mark (Mandatory)', 'Safety requirements for toys having at least one function dependent on electricity.', ARRAY['electric toys', 'safety']::text[], 'https://www.bis.gov.in/product-certification/', 'Safety requirements for toys having at least one function dependent on electricity. Heating: Accessible surfaces of electric toys shall not attain a temperature rise exceeding the specified limits under normal use.', 'Sample');
INSERT INTO public.chunks (document_id, chunk_text, clause_ref, heading) SELECT id, 'Safety requirements for toys having at least one function dependent on electricity.', 'Overview', 'Summary' FROM public.documents WHERE doc_key='std-15644';
INSERT INTO public.chunks (document_id, chunk_text, clause_ref, heading) SELECT id, 'Accessible surfaces of electric toys shall not attain a temperature rise exceeding the specified limits under normal use.', 'Clause 9', 'Heating' FROM public.documents WHERE doc_key='std-15644';
INSERT INTO public.documents (doc_key, standard_number, title, division, sector, year, status, enforcement, summary, tags, source_url, full_text, data_origin) VALUES ('std-7874', 'IS 7874', 'Aluminium alloy castings for general engineering purposes', 'Metallurgical Engineering (MTD)', 'Metals', 2020, 'Under revision', 'Voluntary', 'Composition and mechanical property requirements for aluminium alloy castings used in general engineering.', ARRAY['aluminium', 'castings']::text[], 'https://www.bis.gov.in/standards/', 'Composition and mechanical property requirements for aluminium alloy castings used in general engineering. Mechanical properties: Castings shall meet the minimum tensile strength and elongation values prescribed for the designated alloy.', 'Sample');
INSERT INTO public.chunks (document_id, chunk_text, clause_ref, heading) SELECT id, 'Composition and mechanical property requirements for aluminium alloy castings used in general engineering.', 'Overview', 'Summary' FROM public.documents WHERE doc_key='std-7874';
INSERT INTO public.chunks (document_id, chunk_text, clause_ref, heading) SELECT id, 'Castings shall meet the minimum tensile strength and elongation values prescribed for the designated alloy.', 'Clause 6', 'Mechanical properties' FROM public.documents WHERE doc_key='std-7874';
INSERT INTO public.documents (doc_key, standard_number, title, division, sector, year, status, enforcement, summary, tags, source_url, full_text, data_origin) VALUES ('std-15883', 'IS 15883', 'Fire safety in buildings — Code of practice (selected parts)', 'Civil Engineering (CED)', 'Construction Safety', 2009, 'Active', 'Voluntary', 'Guidance on fire safety management, evacuation planning and fire fighting installations in buildings.', ARRAY['fire safety', 'buildings', 'code of practice']::text[], 'https://www.bis.gov.in/standards/', 'Guidance on fire safety management, evacuation planning and fire fighting installations in buildings. Fire safety management: Occupancies shall maintain a documented fire safety plan with responsibilities, drills and periodic inspection records.', 'Sample');
INSERT INTO public.chunks (document_id, chunk_text, clause_ref, heading) SELECT id, 'Guidance on fire safety management, evacuation planning and fire fighting installations in buildings.', 'Overview', 'Summary' FROM public.documents WHERE doc_key='std-15883';
INSERT INTO public.chunks (document_id, chunk_text, clause_ref, heading) SELECT id, 'Occupancies shall maintain a documented fire safety plan with responsibilities, drills and periodic inspection records.', 'Clause 5', 'Fire safety management' FROM public.documents WHERE doc_key='std-15883';
INSERT INTO public.schemes (scheme_key, name, short_name, description, eligibility, steps, documents_required, source_url, data_origin) VALUES ('scheme-isi', 'Product Certification Scheme (ISI Mark)', 'ISI Mark', 'Licence to apply the BIS Standard Mark (ISI Mark) on a product manufactured in conformity with the relevant Indian Standard, backed by factory inspection and sample testing.', 'Any manufacturer with in-house production and testing facilities for the product covered by an Indian Standard. Applies to Indian factories; overseas factories use FMCS.', '[{"title":"Check eligibility","detail":"Confirm the product is covered by an Indian Standard and identify mandatory vs voluntary status.","duration":"1-2 days"},{"title":"Prepare factory and test setup","detail":"Install required in-house testing facilities and calibrate equipment.","duration":"2-4 weeks"},{"title":"Submit application online","detail":"Apply via the BIS Manakonline portal with documents and application fee.","duration":"1 day"},{"title":"Preliminary factory inspection","detail":"A BIS officer verifies manufacturing capability, QC and testing competence, and draws samples.","duration":"2-4 weeks"},{"title":"Independent sample testing","detail":"Samples are tested in a BIS recognized lab against the relevant Indian Standard.","duration":"2-3 weeks"},{"title":"Grant of licence","detail":"On satisfactory inspection and test results, the licence to use the Standard Mark is granted.","duration":"1-2 weeks"},{"title":"Surveillance and renewal","detail":"Periodic surveillance inspections and market samples; licence renewed with marking fee.","duration":"Annual / as per licence"}]'::jsonb, '["Application form (Form-I) with fee","Factory registration / Udyam or incorporation proof","Manufacturing process flow chart and machinery list","List of in-house test equipment and calibration certificates","Test report from a BIS recognized laboratory","Layout plan of the factory premises"]'::jsonb, 'https://www.bis.gov.in/product-certification/', 'Sample');
INSERT INTO public.schemes (scheme_key, name, short_name, description, eligibility, steps, documents_required, source_url, data_origin) VALUES ('scheme-crs', 'Compulsory Registration Scheme', 'CRS', 'Self-declaration based registration for notified electronics and IT products. The manufacturer registers with BIS after testing in a BIS recognized lab and uses the Standard Mark with an R-number.', 'Manufacturers (Indian or foreign) of products notified under the Electronics and IT Goods Order.', '[{"title":"Confirm product is notified","detail":"Check the product against the notified electronics list and applicable IS.","duration":"1 day"},{"title":"Test at BIS recognized lab","detail":"Submit samples for testing against the relevant Indian Standard.","duration":"2-4 weeks"},{"title":"Apply for registration","detail":"File the online application with the test report and documents.","duration":"1 day"},{"title":"Scrutiny and clarifications","detail":"BIS scrutinizes the application and may raise queries.","duration":"1-3 weeks"},{"title":"Grant of registration","detail":"Registration number (R-number) granted; Standard Mark can be applied.","duration":"1-2 weeks"},{"title":"Renewal and surveillance","detail":"Renew registration periodically; market surveillance samples may be drawn.","duration":"Every 2 years"}]'::jsonb, '["Online registration application","Test report from BIS recognized lab (not older than 90 days)","Business/factory registration documents","Trademark authorization, if applicable","Authorized Indian Representative details (for foreign manufacturers)"]'::jsonb, 'https://www.bis.gov.in/product-certification/', 'Sample');
INSERT INTO public.schemes (scheme_key, name, short_name, description, eligibility, steps, documents_required, source_url, data_origin) VALUES ('scheme-hallmark', 'Hallmarking of Precious Metal Jewellery', 'Hallmarking', 'Registration of jewellers to sell hallmarked gold and silver jewellery, with purity marked at BIS recognized Assaying and Hallmarking Centres and a unique HUID for traceability.', 'Jewellers selling gold or silver jewellery; registration is free and has no expiry in the current framework.', '[{"title":"Register as a jeweller","detail":"Register on the BIS hallmarking portal for each sales outlet.","duration":"2-5 days"},{"title":"Choose an AHC","detail":"Select a BIS recognized Assaying and Hallmarking Centre to send jewellery to.","duration":"1 day"},{"title":"Submit jewellery for assay","detail":"The AHC determines purity and applies the hallmark with HUID.","duration":"1-3 days per lot"},{"title":"Sell hallmarked items only","detail":"Sell only HUID hallmarked jewellery in notified districts, and display the BIS hallmark information.","duration":"Ongoing"},{"title":"Maintain records","detail":"Retain assay and HUID records; be ready for BIS surveillance and consumer purity checks.","duration":"Ongoing"}]'::jsonb, '["Jeweller registration on the BIS portal","GST registration certificate","Proof of business address for each outlet","Identity proof of the proprietor / partners / directors"]'::jsonb, 'https://www.bis.gov.in/hallmarking/', 'Sample');
INSERT INTO public.schemes (scheme_key, name, short_name, description, eligibility, steps, documents_required, source_url, data_origin) VALUES ('scheme-fmcs', 'Foreign Manufacturers Certification Scheme', 'FMCS', 'Certification route for factories located outside India to obtain a licence to use the BIS Standard Mark on products exported to India.', 'Overseas manufacturing units producing goods covered by Indian Standards and intended for the Indian market.', '[{"title":"Appoint an Authorized Indian Representative","detail":"A resident AIR is mandatory for all FMCS applications.","duration":"1-2 weeks"},{"title":"Submit FMCS application","detail":"File the application with documents and prescribed fees.","duration":"1 week"},{"title":"Recording and scrutiny","detail":"BIS records the application and raises clarifications if needed.","duration":"2-4 weeks"},{"title":"Factory inspection abroad","detail":"BIS officers audit the overseas factory and draw samples.","duration":"4-8 weeks"},{"title":"Testing and agreement","detail":"Samples tested in India or a recognized lab; licence agreement and bank guarantee executed.","duration":"4-6 weeks"},{"title":"Grant and surveillance","detail":"Licence granted; periodic surveillance audits follow.","duration":"Annual"}]'::jsonb, '["Application in the prescribed FMCS form with fees in USD","Nomination of an Authorized Indian Representative","Factory and quality documentation","In-house test facility and calibration records","Performance bank guarantee / agreement documents"]'::jsonb, 'https://www.bis.gov.in/product-certification/', 'Sample');
INSERT INTO public.schemes (scheme_key, name, short_name, description, eligibility, steps, documents_required, source_url, data_origin) VALUES ('scheme-lab', 'Laboratory Recognition Scheme', 'Lab Recognition', 'Recognition of independent third-party laboratories to test samples on behalf of BIS for certification and surveillance purposes.', 'NABL accredited laboratories with the required scope, equipment and qualified technical personnel.', '[{"title":"Apply with scope","detail":"Submit the recognition application listing standards and products to be tested.","duration":"1-2 weeks"},{"title":"Document review","detail":"BIS reviews accreditation, quality manual and capability.","duration":"3-4 weeks"},{"title":"Lab assessment visit","detail":"Assessors verify equipment, competence and test procedures on site.","duration":"4-6 weeks"},{"title":"Proficiency testing","detail":"Lab may be asked to test blind samples to demonstrate competence.","duration":"2-4 weeks"},{"title":"Grant of recognition","detail":"Recognition granted for the approved scope, subject to periodic review.","duration":"2-3 weeks"}]'::jsonb, '["Application for recognition with the requested scope","NABL accreditation certificate and scope","Equipment list with calibration status","Technical personnel qualifications","Quality manual"]'::jsonb, 'https://www.bis.gov.in/laboratory/', 'Sample');
INSERT INTO public.schemes (scheme_key, name, short_name, description, eligibility, steps, documents_required, source_url, data_origin) VALUES ('scheme-clubs', 'Standards Clubs', 'Standards Clubs', 'School and college level clubs mentored by BIS to build a quality and standards culture among students through activities, projects and visits.', 'Recognized schools and colleges with a nominated teacher mentor and a minimum group of students.', '[{"title":"Institution applies","detail":"School or college applies to the nearest BIS branch office.","duration":"1-2 weeks"},{"title":"Mentor and members enrolled","detail":"A teacher mentor and student members are registered.","duration":"1 week"},{"title":"Club activation","detail":"BIS provides guidance, standards literature and activity calendar.","duration":"2-4 weeks"},{"title":"Activities and projects","detail":"Quizzes, industry visits, projects on standards and quality.","duration":"Academic year"}]'::jsonb, '["Institution application with school/college details","Nominated teacher mentor consent","List of enrolled student members"]'::jsonb, 'https://www.bis.gov.in/standards-clubs/', 'Sample');
INSERT INTO public.schemes (scheme_key, name, short_name, description, eligibility, steps, documents_required, source_url, data_origin) VALUES ('scheme-training', 'Training and Capacity Building (NITS)', 'Training', 'Training programmes by the National Institute of Training for Standardization for industry, MSMEs, regulators and consumers on standards and certification.', 'Open to industry professionals, MSME staff, students, lab personnel and government officials.', '[{"title":"Browse the calendar","detail":"Check the published training calendar for relevant programmes.","duration":"1 day"},{"title":"Nominate participants","detail":"Submit the nomination form with participant details.","duration":"1 week"},{"title":"Confirmation and fees","detail":"Seat confirmed on payment of course fee.","duration":"1 week"},{"title":"Attend and certify","detail":"Attend the programme and receive a participation certificate.","duration":"2-5 days"}]'::jsonb, '["Nomination form from the organisation","Participant details","Course fee payment proof"]'::jsonb, 'https://www.bis.gov.in/training/', 'Sample');